import { CircleAlert, CircleCheck, GitBranch } from "lucide-react";
import type { RunStatus } from "../types";

// Complete static class strings, not assembled at render time: Tailwind scans
// source for whole class names, so a template-interpolated modifier is only
// generated by accident of the literal appearing somewhere in this file.
const STATUS = {
  ok: { label: "ok", className: "badge badge-sm badge-success gap-1", Icon: CircleCheck },
  failed: { label: "failed", className: "badge badge-sm badge-error gap-1", Icon: CircleAlert },
  diverged: {
    label: "diverged",
    className: "badge badge-sm badge-warning gap-1",
    Icon: GitBranch,
  },
} as const;

export default function StatusBadge({ status }: { status: RunStatus }) {
  const { label, className, Icon } = STATUS[status];
  return (
    <span className={className}>
      <Icon aria-hidden="true" className="size-3" />
      {label}
    </span>
  );
}
